import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>عندما تبني PDF من صور، فإن صيغة تلك الصور تهم أكثر مما تتوقع. تؤثر في حجم الملف وحدة النص وكيفية طباعة المستند.</p>\n<p>الاختيار يؤثر في حجم الملف وحدة النص وطباعة PDF. الصيغة الخاطئة تعني ملفًا ضخمًا أو نصًا ضبابيًا.</p>\n<p>يقارن هذا المقال JPG وPNG داخل ملفات PDF، لتختار الصيغة الصحيحة لكل نوع مستند، مع <a href=\"/ar/tahwil-as-suwar-ila-pdf/\">محول الصور إلى PDF</a>.</p>\n<h2 id=\"jpg-inside-pdf\">صور JPG داخل PDF</h2>\n<p>صور JPG داخل PDF مضغوطة بكفاءة. PDF يخزن JPG كما هو دون إعادة ترميز، فيبقى الملف صغيرًا والصور واضحة.</p>\n<p>للصور الفوتوغرافية في PDF، JPG هو الخيار الطبيعي. يعطي أصغر ملف بأفضل جودة، ويعمل في كل قارئ PDF.</p>\n<h2 id=\"png-inside-pdf\">صور PNG داخل PDF</h2>\n<p>صور PNG داخل PDF تحفظ كل بكسل بدقة دون فقدان. النصوص والرسوم تبقى حادة تمامًا، لكن الملفات أكبر بكثير.</p>\n<p>للنصوص والرسوم في PDF، PNG يتفوق. الحروف تبقى نظيفة والخطوط حادة، وهذا ما يجعله الخيار الصحيح للمستندات النصية.</p>\n<h2 id=\"file-size-comparison\">حجم الملف: الفرق الكبير</h2>\n<p>حجم الملف: الفرق الكبير. PDF بصور JPG قد يزن ميغابايتًا واحدًا، بينما PDF نفسه بصور PNG قد يزن 10 ميغابايت.</p>\n<p>الفرق يهم عند الإرسال عبر البريد أو الرفع إلى بوابات ذات حدود حجم. JPG يختصر حجم الملف دون فقدان جودة مرئية للصور.</p>\n<h2 id=\"text-sharpness\">حدة النص: حيث يفوز PNG</h2>\n<p>حدة النص: حيث يفوز PNG. النص في صورة JPG قد يبدو ضبابيًا عند التكبير، بينما النص في PNG يبقى حادًا تمامًا.</p>\n<p>إذا كان مستندك يحمل نصًا صغيرًا مهمًا، فاختر PNG. وضوح النص يستحق الكيلوبايتات الإضافية.</p>\n<h2 id=\"photo-documents\">المستندات ذات الصور: الصور الشخصية وصور الهوية</h2>\n<p>المستندات ذات الصور: صور شخصية وصور مستندات الهوية. للصور الشخصية في PDF، JPG أفضل لأنه أصغر ويحافظ على جودة الوجه.</p>\n<p>لصور الهوية، استخدم JPG بجودة عالية. الوجه واضح والملف صغير، وهذا ما تحتاجه معظم البوابات.</p>\n<h2 id=\"scanned-documents\">المستندات الممسوحة: العقود والنماذج</h2>\n<p>المستندات الممسوحة: العقود والنماذج. المسح الضوئي يحمل نصًا، لذلك PNG يحافظ على حدته، لكن JPG بجودة عالية يعمل جيدًا أيضًا.</p>\n<p>للعقود والنماذج الطويلة، JPG بجودة 90 يوازن بين وضوح النص وحجم الملف. PNG يناسب الصفحات القليلة ذات النص الصغير جدًا.</p>\n<h2 id=\"transparency-handling\">الشفافية: ماذا يحدث لها؟</h2>\n<p>الشفافية: ماذا يحدث لها؟ PDF يدعم الشفافية، لكن JPG لا يدعمها. عند وضع PNG شفاف في PDF، تبقى الشفافية سليمة.</p>\n<p>إذا حوّلت PNG شفافًا إلى JPG قبل البناء، فستفقد الشفافية. وللتحويل المسبق، استخدم <a href=\"/ar/tahwil-png-ila-jpg/\">محول PNG إلى JPG</a> مع لون تعبئة مناسب.</p>\n<h2 id=\"quality-settings\">إعدادات الجودة لكل صيغة</h2>\n<p>إعدادات الجودة لكل صيغة: لـJPG استخدم جودة 85 إلى 90، ولـPNG لا حاجة إلى إعداد جودة لأنه دون فقدان.</p>\n<p>الجودة الأعلى تعني ملف PDF أكبر. للمشاركة عبر البريد، اختر جودة متوازنة لتقليل حجم الملف.</p>\n<h2 id=\"mixed-batches\">الدفعات المختلطة: صور ومسح ضوئي معًا</h2>\n<p>الدفعات المختلطة: صور ومسح ضوئي معًا. استخدم JPG للصور الفوتوغرافية وPNG للنصوص والرسوم في PDF نفسه.</p>\n<p>المزج يعطي أفضل النتيجتين: ملف صغير ونص حاد. لا حاجة إلى صيغة واحدة لكل شيء.</p>\n<h2 id=\"which-to-choose\">أي صيغة تختار؟</h2>\n<p>أي صيغة تختار؟ القاعدة بسيطة: صور فوتوغرافية فـJPG، ونصوص ورسوم فـPNG، ومزيج فكل صورة بصيغتها المناسبة.</p>\n<p>عند الشك، جرّب الصيغتين وقارن حجم الملف وجودة النص. الاختبار العملي يستغرق دقيقة ويحسم القرار.</p>\n<h2 id=\"real-examples\">ثلاثة أمثلة حقيقية</h2>\n<p>ثلاثة أمثلة حقيقية: سيرة ذاتية بصور JPG تزن 200 كيلوبايت، وعقد ممسوح بصور PNG يزن 2 ميغابايت، وتقرير مختلط يزن 800 كيلوبايت.</p>\n<p>الأمثلة توضح أن الاختيار الصحيح يوفّر ميغابايتات. الصيغة المناسبة لكل محتوى هي سر الملف الصغير.</p>\n<h2 id=\"workflow-tips\">نصائح سير عمل لملفات PDF أفضل</h2>\n<p>نصائح سير عمل لملفات PDF أفضل: حوّل الصور قبل البناء لا أثناءه، ورتب الصفحات مسبقًا، وراجع النتيجة قبل الإرسال.</p>\n<p>التنظيم المسبق يختصر الوقت ويمنع الأخطاء. ملف PDF الجيد يبدأ من صور جاهزة بشكل صحيح.</p>\n<h2 id=\"resolution-and-dpi\">الدقة وDPI داخل ملفات PDF</h2>\n<p>الدقة وDPI داخل ملفات PDF: DPI يحدد حجم الطباعة لا جودة الشاشة. مسح بدقة 200 نقطة في البوصة كافٍ لمعظم المستندات.</p>\n<p>الدقة الأعلى تعني ملفًا أكبر دون فائدة للشاشة. للطباعة الجيدة، استخدم 300 نقطة في البوصة.</p>\n<h2 id=\"colour-rgb-grayscale\">اللون: صفحات RGB مقابل التدرج الرمادي</h2>\n<p>اللون: صفحات RGB مقابل التدرج الرمادي. معظم المستندات تُعرض على الشاشة بألوان RGB، والتدرج الرمادي يصغّر الملف للنصوص فقط.</p>\n<p>إذا كان مستندك نصًا أسود على أبيض، فحوّله إلى تدرج رمادي لتوفير الحجم. الألوان لا تضيف شيئًا للنص العادي.</p>\n<h2 id=\"convert-photos-before\">متى تحوّل الصور قبل البناء؟</h2>\n<p>متى تحوّل الصور قبل البناء؟ عندما تكون بصيغة غير مناسبة: PNG فوتوغرافية ضخمة أو HEIC لا يقبلها قارئ PDF.</p>\n<p>حوّل PNG الفوتوغرافية إلى JPG باستخدام <a href=\"/ar/tahwil-png-ila-jpg/\">محول PNG إلى JPG</a>، وحوّل HEIC باستخدام <a href=\"/ar/tahwil-heic-ila-jpg/\">محول HEIC إلى JPG</a>. التحويل المسبق يختصر حجم الملف.</p>\n<h2 id=\"upload-portal-limits\">حدود حجم الملف في بوابات الرفع</h2>\n<p>حدود حجم الملف في بوابات الرفع: كثير من البوابات تحدد ملف PDF بـ5 أو 10 ميغابايت. PDF بصور PNG قد يتجاوز الحد بسهولة.</p>\n<p>إذا تجاوز ملفك الحد، فأعد بناءه بصور JPG أو اخفض الجودة. الحجم المناسب يضمن قبول الملف من أول مرة.</p>\n<h2 id=\"scanning-at-right-dpi\">كيف تمسح بالـDPI الصحيح؟</h2>\n<p>كيف تمسح بالـDPI الصحيح؟ للمستندات النصية استخدم 200 نقطة في البوصة، وللصور الفوتوغرافية 300، وللأرشيف 600.</p>\n<p>الدقة الأعلى تعني ملفًا أكبر دون فائدة للاستخدام اليومي. وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/dalil-tahwil-as-suwar-ila-pdf/\">الدليل الكامل لتحويل الصورة إلى PDF</a> و<a href=\"/ar/blog/kayfiyya-tahwil-as-sura-ila-pdf/\">كيفية تحويل صورة إلى PDF</a>. وللتحويل المسبق، جرّب <a href=\"/ar/tahwil-as-suwar/\">محول الصور</a> أو <a href=\"/ar/tahwil-jpg-ila-png/\">محول JPG إلى PNG</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل يمكنني مزج صور JPG وPNG في PDF نفسه؟","answer":"نعم، يمكنك مزج JPG وPNG في PDF نفسه. استخدم JPG للصور الفوتوغرافية وPNG للنصوص والرسوم، وسيتعامل PDF مع كل صورة حسب صيغتها."},{"question":"لماذا ملف PDF بصور PNG أكبر بكثير من ملف JPG؟","answer":"لأن PNG يحفظ الصور دون فقدان، فملفاته أكبر بكثير. صورة فوتوغرافية بصيغة PNG قد تكون أكبر بعشر مرات من JPG نفسه. حوّل الصور الفوتوغرافية إلى JPG قبل البناء."},{"question":"هل تطبع JPG أم PNG أفضل من PDF؟","answer":"كلاهما يطبع جيدًا، لكن JPG يعطي نتائج أفضل للصور الفوتوغرافية بحجم أصغر. PNG يتفوق في النصوص والرسوم الدقيقة عند الطباعة."},{"question":"هل يجب تحويل مسح JPG إلى PNG قبل إنشاء PDF؟","answer":"ليس ضروريًا. مسح JPG بجودة عالية يعمل جيدًا في PDF. حوّل إلى PNG فقط إذا كان النص صغيرًا جدًا ويحتاج حدة كاملة."},{"question":"ما أفضل صيغة لتوقيع ممسوح في PDF؟","answer":"PNG هو الأفضل لتوقيع ممسوح في PDF، لأنه يحافظ على حدة الخطوط. إذا كان التوقيع على خلفية بيضاء، فـJPG يعمل أيضًا بحجم أصغر."},{"question":"هل يمكنني تصغير حجم PDF مصنوع من صور PNG؟","answer":"نعم، أعد بناء PDF بصور JPG بدل PNG، أو اخفض جودة الصور في إعدادات PDF. التحويل المسبق للصور إلى JPG يصغّر الملف بشكل كبير."}];
